/* ─── 10. Date range validation (From / To typed) ─── */
export const RangeValidation: Story = {
  name: "Date Range Validation (From / To)",
  render: () => <RangeValidationDemo />,
};

function RangeValidationDemo() {
  const [start, setStart] = useState<Date | null>(null);
  const [end, setEnd] = useState<Date | null>(new Date(2023, 0, 18)); // 01-18-2023, matches doc

  // Filling 'End' before 'Start' is invalid; the error surfaces on the End field
  // (per the doc: End is filled while Start is still empty / out of order).
  const endError =
    end && !start
      ? "'Start' date field cannot be empty"
      : start && end && start.getTime() > end.getTime()
        ? "'Start' date must be before 'End' date"
        : undefined;

  return (
    <div style={{ padding: 24, display: "flex", gap: 24, flexWrap: "wrap" as const }}>
      <div style={{ maxWidth: 260 }}>
        <IdsDatePicker label="Start" required value={start} onChange={(d) => setStart(d)} />
      </div>
      <div style={{ maxWidth: 260 }}>
        <IdsDatePicker
          label="End"
          required
          value={end}
          onChange={(d) => setEnd(d)}
          error={!!endError}
          errorMessage={endError}
        />
      </div>
    </div>
  );
}

/* ─── 11. Date range picker — two aligned fields sharing one range ─── */
export const DateRangePicker: Story = {
  name: "Date Range Picker (two fields)",
  render: () => <DateRangePickerDemo />,
};

function DateRangePickerDemo() {
  const today = new Date();
  const y = today.getFullYear();
  const m = today.getMonth();
  // Preset a range so both fields show a value and either calendar highlights it.
  const [start, setStart] = useState<Date | null>(new Date(y, m, 8));
  const [end, setEnd] = useState<Date | null>(new Date(y, m, 16));

  const shared = {
    rangeMode: true as const,
    rangeStart: start,
    rangeEnd: end,
    onRangeChange: (s: Date | null, e: Date | null) => {
      setStart(s);
      setEnd(e);
    },
  };

  return (
    <div style={{ padding: 24, paddingBottom: 520 }}>
      <div style={{ display: "flex", gap: 16, alignItems: "flex-start" }}>
        <div style={{ maxWidth: 220 }}>
          <IdsDatePicker label="Start date" rangeField="start" {...shared} />
        </div>
        <div style={{ maxWidth: 220 }}>
          <IdsDatePicker label="End date" rangeField="end" {...shared} />
        </div>
      </div>
      <p style={{ marginTop: 12, fontSize: 12, color: "var(--color-text-neutral)" }}>
        Two horizontally aligned pickers share one range. Open either calendar and pick two
        dates — the overlay highlights the range while selecting, and both fields update.
      </p>
    </div>
  );
}

